export function icon(name,size=22){if(detailed[name])return `<svg class="pixel-icon" width="${size}" height="${size}" viewBox="0 0 16 16" aria-hidden="true" shape-rendering="crispEdges"><path fill-rule="evenodd" d="${detailed[name]}"/></svg>`;if(['happy','calm','neutral','sad','cry','angry','tired','sleep'].includes(name)){const color={happy:'#e9ae6f',calm:'#a4afc6',neutral:'#d9c2ad',sad:'#a3a6cf',cry:'#c0cfea',angry:'#ad8270',tired:'#9489bd',sleep:'#7382a9'}[name];return `<svg class="pixel-icon cat-face" width="${size}" height="${size}" viewBox="0 0 16 16" shape-rendering="crispEdges" aria-hidden="true"><path fill="${color}" d="M2 2h3v2h6V2h3v10h-2v2H4v-2H2z"/><path fill="#f4b7c4" d="M3 3h1v2H3zm9 0h1v2h-1z"/><path fill="#e7c8a6" d="M4 10h8v3H4z"/><path fill="#0b182b" d="M4 7h2v${['sleep','tired'].includes(name)?1:2}H4zm6 0h2v${['sleep','tired'].includes(name)?1:2}h-2zm-3 3h2v1H7z"/></svg>`}return `<svg class="pixel-icon" width="${size}" height="${size}" viewBox="0 0 7 7" aria-hidden="true" shape-rendering="crispEdges">${(glyphs[name]||glyphs.home).flatMap((row,y)=>[...row].map((c,x)=>c==='1'?`<path d="M${x} ${y}h1v1h-1z"/>`:'')).join('')}</svg>`}
export function bar(value,label='',color='cyan'){const v=Math.max(0,Math.min(100,Number(value)||0));return `<div class="blockbar ${color}" role="progressbar" aria-label="${esc(label)}" aria-valuenow="${v}" aria-valuemin="0" aria-valuemax="100">${Array.from({length:24},(_,i)=>`<i class="${i<Math.round(v/100*24)?'lit':''}"></i>`).join('')}</div>`}
export function panel(title,content,extra='',cls=''){return `<section class="panel ${cls}"><div class="panel-head"><h2>${title}</h2>${extra}</div>${content}</section>`}
export const badge=(text,cls='')=>`<span class="badge ${cls}">${esc(text)}</span>`;
export const button=(text,action,extra='',cls='')=>`<button class="button ${cls}" data-action="${action}" ${extra}>${text}</button>`;
export function input(name,label,value='',type='text',extra=''){return `<label class="field"><span>${label}</span><input name="${name}" type="${type}" value="${esc(value)}" ${extra}></label>`}
export function area(name,label,value='',extra=''){return `<label class="field"><span>${label}</span><textarea name="${name}" ${extra}>${esc(value)}</textarea></label>`}
export function select(name,label,options,value='',extra=''){return `<label class="field"><span>${label}</span><select name="${name}" ${extra}>${options.map(o=>`<option ${o===value?'selected':''} value="${esc(o)}">${esc(o)}</option>`).join('')}</select></label>`}
export function tabs(items,current,key){return `<div class="tabs" role="group" aria-label="页面选项">${items.map(([id,label])=>`<button data-action="tab" data-key="${key}" data-value="${id}" aria-pressed="${id===current}" class="${id===current?'active':''}">${label}</button>`).join('')}</div>`}
export const empty=(text)=>`<div class="empty">${icon('vault',28)}<p>${text}</p></div>`;
